public sealed class ReportHttpRazorTests
{
    [Fact]
    public async Task Api_auth_bearer_cookie_permission_validation_and_no_proposed_routes()
    { await using var h = await Host.Start(); using var c = h.Client(); using (var r = await c.GetAsync("/api/reports/assets")) Assert.Equal(HttpStatusCode.Unauthorized, r.StatusCode); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); using (var r = await c.GetAsync("/api/reports/assets")) Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); c.DefaultRequestHeaders.Remove("Cookie"); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("user", AuthClientType.Mobile)); using (var r = await c.GetAsync("/api/reports/assets")) Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); using (var r = await c.GetAsync("/api/reports/assets?pageSize=101")) Assert.Equal((HttpStatusCode)422, r.StatusCode); using (var r = await c.GetAsync("/api/reports/assets?page=invalid")) Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); using (var r = await c.GetAsync("/api/reports/stock-empty?section=R12")) Assert.Equal((HttpStatusCode)422, r.StatusCode); using (var r = await c.GetAsync("/api/reports/R12")) Assert.Equal(HttpStatusCode.NotFound, r.StatusCode); using (var r = await c.PostAsJsonAsync("/api/reports/assets", new { })) Assert.Equal(HttpStatusCode.MethodNotAllowed, r.StatusCode); }
    [Theory]
    [InlineData("assets", "R01")]
    [InlineData("assets-by-category", "R02")]
    [InlineData("stock-empty", "R03")]
    [InlineData("stock-low", "R04")]
    public async Task All_four_api_routes_have_correct_report_metadata_and_no_store(string route, string code)
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); using var r = await c.GetAsync("/api/reports/" + route); r.EnsureSuccessStatusCode(); Assert.Contains("no-store", r.Headers.CacheControl!.ToString(), StringComparison.Ordinal); var report = (await r.Content.ReadFromJsonAsync<ReportResult>())!; Assert.Equal(code, report.ReportCode); Assert.Equal("DRAFT_DEMO", report.DataState); Assert.Equal(h.F.Base.Clock.GetUtcNow(), report.ReadAtUtc); Assert.Equal(0, h.F.Inventory.Writes); }
    [Fact]
    public async Task Api_viewer_export_denied_scope_counts_not_page_and_revoke_old_session()
    { await using var h = await Host.Start(); await h.F.Assets([h.F.Asset("OWN"), h.F.Asset("HIDDEN", category: "CAT-OTHER", name: "HIDDEN-REPORT-CANARY")]); await h.F.Base.Grant(AuthRole.Viewer, category: "CAT-CHILD", descendants: false); using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("user", AuthClientType.Mobile)); using (var r = await c.GetAsync("/api/reports/assets?page=2&pageSize=1")) { r.EnsureSuccessStatusCode(); var report = (await r.Content.ReadFromJsonAsync<ReportResult>())!; Assert.Empty(report.Assets); Assert.Equal(1, report.Total); Assert.Equal(1, report.Summary.AssetCount); } using (var r = await c.GetAsync("/api/reports/assets/export")) Assert.Equal(HttpStatusCode.Forbidden, r.StatusCode); using (var r = await c.GetAsync("/api/reports/assets?categoryId=CAT-OTHER")) Assert.Equal(HttpStatusCode.NotFound, r.StatusCode); await h.F.Base.Auth.MutateAsync(s => { var i = s.Users.FindIndex(u => u.UserId == "USER"); s.Users[i] = s.Users[i] with { SecurityVersion = s.Users[i].SecurityVersion + 1 }; return true; }); using (var r = await c.GetAsync("/api/reports/assets")) Assert.Equal(HttpStatusCode.Unauthorized, r.StatusCode); }
    [Fact]
    public async Task Api_export_attachment_contains_all_allowed_rows_and_preserves_source_missing_min_unknown()
    { await using var h = await Host.Start(); h.F.Snapshot(h.F.Item("LOW"), 2, 5); h.F.Snapshot(h.F.Item("NOMIN"), 2, null); using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); using var r = await c.GetAsync("/api/reports/stock-low/export?pageSize=1&page=99"); r.EnsureSuccessStatusCode(); Assert.Equal("text/csv", r.Content.Headers.ContentType!.MediaType); Assert.Equal("attachment", r.Content.Headers.ContentDisposition!.DispositionType); Assert.Contains("R04-DRAFT", r.Content.Headers.ContentDisposition.FileName!, StringComparison.Ordinal); Assert.Equal("nosniff", r.Headers.GetValues("X-Content-Type-Options").Single()); var bytes = await r.Content.ReadAsByteArrayAsync(); Assert.Equal(new byte[] { 239, 187, 191 }, bytes.Take(3)); var text = Encoding.UTF8.GetString(bytes); Assert.Contains("LOW", text, StringComparison.Ordinal); Assert.Contains("Snapshot GIẢ", text, StringComparison.Ordinal); using var missing = await c.GetAsync("/api/reports/stock-low?section=MISSING_MINIMUM"); missing.EnsureSuccessStatusCode(); var report = (await missing.Content.ReadFromJsonAsync<ReportResult>())!; Assert.Equal("NOMIN", report.Stock.Single().ItemId); Assert.Null(report.Stock.Single().Minimum); }
    [Fact]
    public async Task Upstream_api_returns_safe503_without_fake_zero_result()
    { await using var h = await Host.Start(); h.F.Inventory.FailRead = true; using var c = h.Client(); c.DefaultRequestHeaders.Authorization = new("Bearer", await h.Login("admin", AuthClientType.Mobile)); using var r = await c.GetAsync("/api/reports/stock-empty"); Assert.Equal(HttpStatusCode.ServiceUnavailable, r.StatusCode); var body = await r.Content.ReadAsStringAsync(); Assert.DoesNotContain("PRIVATE-REPORT-INVENTORY-CANARY", body, StringComparison.Ordinal); Assert.DoesNotContain("assetCount", body, StringComparison.OrdinalIgnoreCase); }
    [Fact]
    public async Task Razor_reports_filter_paging_export_links_preserve_filters_and_partial_path()
    { await using var h = await Host.Start(); await h.F.Assets([h.F.Asset("A1"), h.F.Asset("A2"), h.F.Asset("HIDDEN", category: "CAT-OTHER", name: "HIDDEN-UI-CANARY")]); await h.F.Base.Grant(AuthRole.Viewer, "OU-A", "LOC-A", "CAT-CHILD", false); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("user", AuthClientType.Web)); var html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R01&CategoryId=CAT-CHILD&IncludeDescendants=false&OrgUnitId=OU-A&LocationId=LOC-A&Q=Asset&PageSize=1")); Assert.Contains("2 dòng", html, StringComparison.Ordinal); Assert.Contains("PageNumber=2", html, StringComparison.Ordinal); Assert.Contains("CategoryId=CAT-CHILD", html, StringComparison.Ordinal); Assert.Contains("OrgUnitId=OU-A", html, StringComparison.Ordinal); Assert.Contains("Q=Asset", html, StringComparison.Ordinal); Assert.Contains("[nhánh được phép]", html, StringComparison.Ordinal); Assert.DoesNotContain("HIDDEN-UI-CANARY", html, StringComparison.Ordinal); Assert.DoesNotContain("handler=Export", html, StringComparison.Ordinal); html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R02&GroupLevel=2")); Assert.Contains("Trực tiếp", html, StringComparison.Ordinal); Assert.Contains("Gồm cấp con", html, StringComparison.Ordinal); Assert.DoesNotContain("Máy demo giả", html, StringComparison.Ordinal); }
    [Fact]
    public async Task Razor_stock_empty_unknown_missing_threshold_and_nonstock_sections_with_asof_unit()
    { await using var h = await Host.Start(); h.F.Snapshot(h.F.Item("ZERO"), 0, null); h.F.Snapshot(h.F.Item("LOW"), 1, 2); h.F.Item("UNKNOWN"); h.F.Item("SERVICE", tracked: false, nature: "Dịch vụ"); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); var html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R03")); Assert.Contains("Item ZERO GIẢ", html, StringComparison.Ordinal); Assert.Contains("Snapshot GIẢ", html, StringComparison.Ordinal); Assert.Contains("Chưa có ngưỡng", html, StringComparison.Ordinal); Assert.Contains("Tổng hợp từng đơn vị", html, StringComparison.Ordinal); html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R04&Section=UNKNOWN")); Assert.Contains("Item UNKNOWN GIẢ", html, StringComparison.Ordinal); Assert.Contains("Chưa có thời điểm số liệu", html, StringComparison.Ordinal); Assert.Contains("Chưa có tổng xác định", html, StringComparison.Ordinal); html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R03&Section=NOT_TRACKED")); Assert.Contains("Item SERVICE GIẢ", html, StringComparison.Ordinal); html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R03&LocationId=LOC-A&Section=UNKNOWN")); Assert.Contains("Không có dòng phù hợp", html, StringComparison.Ordinal); }
    [Fact]
    public async Task Razor_error_keeps_filter_and_does_not_present_empty_or_leak_private_upstream()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); h.F.Inventory.FailRead = true; using var r = await c.GetAsync("/Reports?Code=R04&Q=GIẢ&Unit=kg&Section=MISSING_MINIMUM"); Assert.Equal(HttpStatusCode.ServiceUnavailable, r.StatusCode); var html = WebUtility.HtmlDecode(await r.Content.ReadAsStringAsync()); Assert.Contains("value=\"GIẢ\"", html, StringComparison.Ordinal); Assert.Contains("value=\"kg\" selected", html, StringComparison.Ordinal); Assert.Contains("MISSING_MINIMUM", html, StringComparison.Ordinal); Assert.DoesNotContain("PRIVATE-REPORT-INVENTORY-CANARY", html, StringComparison.Ordinal); Assert.DoesNotContain("Không có dòng phù hợp", html, StringComparison.Ordinal); Assert.DoesNotContain("Tổng Assets duy nhất", html, StringComparison.Ordinal); }
    [Fact]
    public async Task Razor_validation_binding_access_denied_and_export_authorization()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); using (var r = await c.GetAsync("/Reports?Code=R02&GroupLevel=11")) Assert.Equal((HttpStatusCode)422, r.StatusCode); using (var r = await c.GetAsync("/Reports?Code=R02&PageSize=bad")) Assert.Equal(HttpStatusCode.BadRequest, r.StatusCode); using (var r = await c.GetAsync("/Reports?Code=R12")) Assert.Equal(HttpStatusCode.NotFound, r.StatusCode); await h.F.Base.Grant(AuthRole.Viewer); c.DefaultRequestHeaders.Remove("Cookie"); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("user", AuthClientType.Web)); c.DefaultRequestHeaders.Accept.Add(new("text/html")); using (var r = await c.GetAsync("/Reports?handler=Export&Code=R01")) { Assert.Equal(HttpStatusCode.Redirect, r.StatusCode); Assert.Equal("/Account/AccessDenied", r.Headers.Location!.OriginalString); } }
    [Fact]
    public async Task Razor_default_url_and_omitted_section_keep_defaults_without_required_binding_error()
    { await using var h = await Host.Start(); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); using (var r = await c.GetAsync("/Reports")) { r.EnsureSuccessStatusCode(); Assert.Contains("R01", await r.Content.ReadAsStringAsync(), StringComparison.Ordinal); } using (var r = await c.GetAsync("/Reports?Code=R04")) { r.EnsureSuccessStatusCode(); Assert.Contains("R04", await r.Content.ReadAsStringAsync(), StringComparison.Ordinal); } }
    [Fact]
    public async Task Razor_out_of_range_page_retains_true_total_and_empty_page_feedback()
    { await using var h = await Host.Start(); await h.F.Assets([h.F.Asset("A1")]); using var c = h.Client(); c.DefaultRequestHeaders.Add("Cookie", "dt_session=" + await h.Login("admin", AuthClientType.Web)); var html = WebUtility.HtmlDecode(await c.GetStringAsync("/Reports?Code=R01&PageNumber=99&PageSize=1")); Assert.Contains("Trang hiện tại không có dòng", html, StringComparison.Ordinal); Assert.Contains("phạm vi vẫn là 1", html, StringComparison.Ordinal); }
    private sealed class Host(WebApplication app, ReportFixture f, string address) : IAsyncDisposable
    {
        public ReportFixture F { get; } = f; public HttpClient Client() => new(new HttpClientHandler { AllowAutoRedirect = false }) { BaseAddress = new(address) };
        public async Task<string> Login(string name, AuthClientType type) { var r = await app.Services.GetRequiredService<AuthApplicationService>().LoginAsync(new(name, "fake-password", type, false, "report-http")); Assert.Equal(LoginStatus.Success, r.Status); return r.AccessToken!; }
        public static async Task<Host> Start()
        { var f = await ReportFixture.Start(); var b = WebApplication.CreateBuilder(new WebApplicationOptions { EnvironmentName = "Testing", ApplicationName = typeof(ReportWeb).Assembly.GetName().Name, ContentRootPath = AppContext.BaseDirectory }); b.WebHost.UseKestrel(); b.Logging.ClearProviders(); b.Services.AddRazorPages(); b.Services.AddSingleton(f.Service); b.Services.AddSingleton<IAuthSystemStore>(f.Base.Auth); b.Services.AddSingleton<IPasswordHashService>(new TestPasswordHashService()); b.Services.AddSingleton(new AuthPolicyOptions()); b.Services.AddSingleton<TimeProvider>(f.Base.Clock); b.Services.AddSingleton<AuthApplicationService>(); b.Services.AddAuthentication(OpaqueSessionAuthenticationHandler.SchemeName).AddScheme<AuthenticationSchemeOptions, OpaqueSessionAuthenticationHandler>(OpaqueSessionAuthenticationHandler.SchemeName, _ => { }); b.Services.AddAuthorization(); var app = b.Build(); app.Urls.Add("http://127.0.0.1:0"); app.UseTask005SessionAuthentication(); app.UseAuthorization(); app.MapTask011ReportApi(); app.MapRazorPages(); await app.StartAsync(); return new(app, f, app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single()); }
        public async ValueTask DisposeAsync() { await app.StopAsync(); await app.DisposeAsync(); }
    }
}
